#!/usr/bin/env node
/**
 * Tests for Story 30.4 — Demerzel/ML removal cross-mirror drift guard.
 *
 * Story 30.4 (FR244-FR247, NFR49) removes the `ma-agent-ml` skill and its 12
 * `ml-*` workflow skills from the BMAD-extension plugin pipeline for NEW
 * installs. That pipeline has two trees that must always agree:
 *   - lib/bmad-extension/skills/        (hand-authored source)
 *   - lib/bmad-extension-plugin/skills/ (generated by scripts/build-plugin.js)
 *
 * A regression here looks like: someone re-adds `ma-agent-ml`/`ml-*` to only
 * one of the two trees (e.g. restores a source dir but forgets to rebuild the
 * plugin, or vice versa via a stale commit), or a future skill addition is
 * silently missed in one tree. This guard fails loudly in either case.
 *
 * This test does NOT run the build — it asserts against whatever the two
 * trees currently contain on disk. Run `npm run build:plugin` first if the
 * generated tree is stale (build-plugin.test.js already covers that the
 * generated tree is always a pure function of source).
 */
'use strict';

const assert = require('assert');
const path = require('path');
const fs = require('fs');

const PROJECT_ROOT = path.join(__dirname, '..');
const SRC_SKILLS_DIR = path.join(PROJECT_ROOT, 'lib', 'bmad-extension', 'skills');
const GENERATED_SKILLS_DIR = path.join(PROJECT_ROOT, 'lib', 'bmad-extension-plugin', 'skills');

let passed = 0;
let failed = 0;
const errors = [];

function test(name, fn) {
  try {
    fn();
    console.log(`  ✓ ${name}`);
    passed++;
  } catch (err) {
    console.error(`  ✗ ${name}: ${err.message}`);
    failed++;
    errors.push({ name, error: err.message });
  }
}

function listSkillDirNames(skillsDir) {
  if (!fs.existsSync(skillsDir)) return [];
  return fs.readdirSync(skillsDir, { withFileTypes: true })
    .filter((e) => e.isDirectory())
    .map((e) => e.name);
}

const REMOVED_DEMERZEL_IDS = Object.freeze([
  'ma-agent-ml',
  'ml-ideation', 'ml-eda', 'ml-architecture', 'ml-detailed-design',
  'ml-techspec', 'ml-infra', 'ml-experiment', 'ml-analysis',
  'ml-hparam', 'ml-advise', 'ml-retrospective', 'ml-revision',
]);

console.log('\n=== Story 30.4: Demerzel/ML removal — cross-mirror drift guard ===');

test('source tree (lib/bmad-extension/skills) exists and is non-empty', () => {
  assert.ok(fs.existsSync(SRC_SKILLS_DIR), 'source skills dir must exist');
  const entries = listSkillDirNames(SRC_SKILLS_DIR);
  assert.ok(entries.length > 0, 'source skills dir must be non-empty');
});

test('generated tree (lib/bmad-extension-plugin/skills) exists and is non-empty', () => {
  if (!fs.existsSync(GENERATED_SKILLS_DIR)) {
    console.log('    (generated tree absent — run `npm run build:plugin` first; skipping remaining assertions)');
    return;
  }
  const entries = listSkillDirNames(GENERATED_SKILLS_DIR);
  assert.ok(entries.length > 0, 'generated skills dir must be non-empty');
});

test('no ma-agent-ml / ml-* directory survives in the SOURCE tree', () => {
  const onDisk = new Set(listSkillDirNames(SRC_SKILLS_DIR));
  const survivors = REMOVED_DEMERZEL_IDS.filter((id) => onDisk.has(id));
  assert.deepStrictEqual(survivors, [],
    `Demerzel/ML skill(s) still present in source tree: ${survivors.join(', ')}`);
});

test('no ma-agent-ml / ml-* directory survives in the GENERATED tree', () => {
  if (!fs.existsSync(GENERATED_SKILLS_DIR)) {
    console.log('    (generated tree absent — run `npm run build:plugin` first; skipping)');
    return;
  }
  const onDisk = new Set(listSkillDirNames(GENERATED_SKILLS_DIR));
  const survivors = REMOVED_DEMERZEL_IDS.filter((id) => onDisk.has(id));
  assert.deepStrictEqual(survivors, [],
    `Demerzel/ML skill(s) still present in generated tree: ${survivors.join(', ')}`);
});

test('source and generated trees agree on the full skill-directory-name set (no other drift)', () => {
  if (!fs.existsSync(GENERATED_SKILLS_DIR)) {
    console.log('    (generated tree absent — run `npm run build:plugin` first; skipping)');
    return;
  }
  const src = new Set(listSkillDirNames(SRC_SKILLS_DIR));
  const gen = new Set(listSkillDirNames(GENERATED_SKILLS_DIR));
  const missingFromGenerated = [...src].filter((n) => !gen.has(n));
  const extraInGenerated = [...gen].filter((n) => !src.has(n));
  assert.deepStrictEqual(missingFromGenerated, [],
    `skill dirs present in source but missing from the generated bundle: ${missingFromGenerated.join(', ')}`);
  assert.deepStrictEqual(extraInGenerated, [],
    `skill dirs present in the generated bundle but absent from source (stale build?): ${extraInGenerated.join(', ')}`);
});

test('module-help.csv (source) carries no bmm-demerzel-keyed row', () => {
  const csvPath = path.join(SRC_SKILLS_DIR, 'module-help.csv');
  assert.ok(fs.existsSync(csvPath), 'source module-help.csv must exist');
  const content = fs.readFileSync(csvPath, 'utf8');
  assert.ok(!content.includes('bmm-demerzel'),
    'source module-help.csv must not contain any bmm-demerzel-keyed row');
});

test('module-help.csv (generated) carries no bmm-demerzel-keyed row', () => {
  const csvPath = path.join(PROJECT_ROOT, 'lib', 'bmad-extension-plugin', 'skills', 'module-help.csv');
  if (!fs.existsSync(csvPath)) {
    console.log('    (generated module-help.csv absent — run `npm run build:plugin` first; skipping)');
    return;
  }
  const content = fs.readFileSync(csvPath, 'utf8');
  assert.ok(!content.includes('bmm-demerzel'),
    'generated module-help.csv must not contain any bmm-demerzel-keyed row');
});

test('marketplace.json.template (source) lists no ma-agent-ml / ml-* skill path', () => {
  const tmplPath = path.join(PROJECT_ROOT, 'lib', 'bmad-extension', '.claude-plugin', 'marketplace.json.template');
  assert.ok(fs.existsSync(tmplPath), 'marketplace.json.template must exist');
  const template = JSON.parse(fs.readFileSync(tmplPath, 'utf8'));
  const skills = (template.plugins && template.plugins[0] && template.plugins[0].skills) || [];
  const survivors = skills.filter((p) => REMOVED_DEMERZEL_IDS.includes(path.basename(p)));
  assert.deepStrictEqual(survivors, [],
    `marketplace.json.template still lists removed Demerzel/ML skill path(s): ${survivors.join(', ')}`);
});

test('rendered marketplace.json (generated) lists no ma-agent-ml / ml-* skill path', () => {
  const renderedPath = path.join(PROJECT_ROOT, 'lib', 'bmad-extension-plugin', '.claude-plugin', 'marketplace.json');
  if (!fs.existsSync(renderedPath)) {
    console.log('    (rendered marketplace.json absent — run `npm run build:plugin` first; skipping)');
    return;
  }
  const rendered = JSON.parse(fs.readFileSync(renderedPath, 'utf8'));
  const skills = (rendered.plugins && rendered.plugins[0] && rendered.plugins[0].skills) || [];
  const survivors = skills.filter((p) => REMOVED_DEMERZEL_IDS.includes(path.basename(p)));
  assert.deepStrictEqual(survivors, [],
    `rendered marketplace.json still lists removed Demerzel/ML skill path(s): ${survivors.join(', ')}`);
});

// ─── bmad-method@6.10.0 fail-loud staging guards (Story 30.1 gate constraint) ───
// v6.10.0 added TWO fail-loud guards to official-modules.js `_copyResolvedSkills`,
// on the SAME custom-source staging path ma-agents' own plugin traverses:
//   (a) an empty/unresolved marketplace-plugin resolution THROWS (was silent);
//   (b) duplicate skill-LEAF names (basename collisions) THROW.
// Removing the ma-agent-ml + 12 ml-* entries from the template must NOT trip
// either: the staged skill set must stay non-empty and every leaf unique, or a
// formerly-silent partial install becomes a HARD failure at 6.10.0.

function templateSkills() {
  const tmplPath = path.join(PROJECT_ROOT, 'lib', 'bmad-extension', '.claude-plugin', 'marketplace.json.template');
  const template = JSON.parse(fs.readFileSync(tmplPath, 'utf8'));
  return (template.plugins && template.plugins[0] && template.plugins[0].skills) || [];
}

test('post-removal template resolves NON-EMPTY (6.10.0 _copyResolvedSkills guard a)', () => {
  const skills = templateSkills();
  assert.ok(Array.isArray(skills) && skills.length > 0,
    'template.plugins[0].skills must be a non-empty array — an empty marketplace-plugin ' +
    'resolution HARD-fails under bmad-method@6.10.0 _copyResolvedSkills');
});

test('post-removal template skill LEAF names are UNIQUE (6.10.0 _copyResolvedSkills guard b)', () => {
  const skills = templateSkills();
  const seen = new Set();
  const dupLeaves = [];
  for (const p of skills) {
    const leaf = path.basename(p);
    if (seen.has(leaf)) dupLeaves.push(leaf);
    seen.add(leaf);
  }
  assert.deepStrictEqual(dupLeaves, [],
    `duplicate skill-leaf name(s) in template: ${dupLeaves.join(', ')} — ` +
    'bmad-method@6.10.0 _copyResolvedSkills HARD-fails on duplicate skill leaves');
});

test('every rendered-bundle skill leaf is unique AND non-empty (6.10.0 staging, rendered mirror)', () => {
  const renderedPath = path.join(PROJECT_ROOT, 'lib', 'bmad-extension-plugin', '.claude-plugin', 'marketplace.json');
  if (!fs.existsSync(renderedPath)) {
    console.log('    (rendered marketplace.json absent — run `npm run build:plugin` first; skipping)');
    return;
  }
  const rendered = JSON.parse(fs.readFileSync(renderedPath, 'utf8'));
  const skills = (rendered.plugins && rendered.plugins[0] && rendered.plugins[0].skills) || [];
  assert.ok(skills.length > 0, 'rendered bundle skills[] must be non-empty (6.10.0 guard a)');
  const seen = new Set();
  const dupLeaves = [];
  for (const p of skills) {
    const leaf = path.basename(p);
    if (seen.has(leaf)) dupLeaves.push(leaf);
    seen.add(leaf);
  }
  assert.deepStrictEqual(dupLeaves, [],
    `duplicate skill-leaf name(s) in rendered bundle: ${dupLeaves.join(', ')} (6.10.0 guard b)`);
});

test('every template skill leaf corresponds to a real on-disk skill dir (non-empty resolution)', () => {
  // Guard (a) is really about RESOLUTION being non-empty, not just the array
  // being non-empty — a listed path that resolves to nothing would stage empty.
  const skills = templateSkills();
  const unresolved = [];
  for (const rel of skills) {
    const abs = path.join(PROJECT_ROOT, 'lib', 'bmad-extension', rel.replace(/^\.\//, ''));
    if (!fs.existsSync(abs) || !fs.statSync(abs).isDirectory()) {
      unresolved.push(rel);
    }
  }
  assert.deepStrictEqual(unresolved, [],
    `template lists skill path(s) that do not resolve to an on-disk dir: ${unresolved.join(', ')} — ` +
    'these would stage an empty/partial resolution and HARD-fail under 6.10.0');
});

test('lib/agents.js carries no bmm-demerzel agent registration', () => {
  const agentsPath = path.join(PROJECT_ROOT, 'lib', 'agents.js');
  const content = fs.readFileSync(agentsPath, 'utf8');
  assert.ok(!/id:\s*['"]bmm-demerzel['"]/.test(content),
    'lib/agents.js must not register bmm-demerzel');
});

test('lib/skill-authoring.js CUSTOM_AGENTS carries no bmm-demerzel entry', () => {
  const p = path.join(PROJECT_ROOT, 'lib', 'skill-authoring.js');
  const content = fs.readFileSync(p, 'utf8');
  assert.ok(!/CUSTOM_AGENTS\s*=\s*\[[^\]]*['"]bmm-demerzel['"]/.test(content),
    'lib/skill-authoring.js CUSTOM_AGENTS must not include bmm-demerzel');
});

// ─── Summary ───────────────────────────────────────────────────────────────
console.log(`\n--- Results: ${passed} passed, ${failed} failed ---`);
if (errors.length > 0) {
  console.error('\nFailures:');
  for (const { name, error } of errors) {
    console.error(`  ${name}: ${error}`);
  }
}
process.exit(failed > 0 ? 1 : 0);
